begin;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select plan(14);
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data)values('1d000000-0000-4000-8000-000000000001','report-owner@example.test','{}','{}'),('1d000000-0000-4000-8000-000000000002','report-member@example.test','{}','{}'),('1d000000-0000-4000-8000-000000000003','report-outsider@example.test','{}','{}');insert into public.workspaces(id,name,owner_id)values('2d000000-0000-4000-8000-000000000001','Report Workspace','1d000000-0000-4000-8000-000000000001'),('2d000000-0000-4000-8000-000000000002','Outside Workspace','1d000000-0000-4000-8000-000000000003');insert into public.workspace_members(workspace_id,user_id,role)values('2d000000-0000-4000-8000-000000000001','1d000000-0000-4000-8000-000000000002','accountant');
set local role authenticated;select throws_ok($$select public.record_export_event('2d000000-0000-4000-8000-000000000001','1d000000-0000-4000-8000-000000000001','denied-export-01','pl','csv','2026-01-01','2026-12-31',1,repeat('a',64),'{}')$$,'42501',null,'authenticated clients cannot call the export recorder');reset role;
create temporary table export_create as select public.record_export_event('2d000000-0000-4000-8000-000000000001','1d000000-0000-4000-8000-000000000001','export-request-0001','schedule-c','spreadsheet','2026-01-01','2026-12-31',12,repeat('b',64),'{"year":2026}')id;
select ok((select id is not null from export_create),'service records an export');select is((select report_type from public.export_events where id=(select id from export_create)),'schedule-c','report type is retained');select is((select export_format from public.export_events where id=(select id from export_create)),'spreadsheet','export format is retained');select is((select row_count from public.export_events where id=(select id from export_create)),12,'row count is retained');select is((select content_sha256 from public.export_events where id=(select id from export_create)),repeat('b',64),'content hash is retained');select is((select count(*)::integer from public.audit_events where request_id='export-request-0001'),1,'export creates an audit event');select is(public.record_export_event('2d000000-0000-4000-8000-000000000001','1d000000-0000-4000-8000-000000000001','export-request-0001','schedule-c','spreadsheet','2026-01-01','2026-12-31',12,repeat('b',64),'{}'),(select id from export_create),'export retries are idempotent');
select throws_ok($$update public.export_events set row_count=99 where request_id='export-request-0001'$$,'P0001','Export history is append-only','export history cannot be updated');select throws_ok($$delete from public.export_events where request_id='export-request-0001'$$,'P0001','Export history is append-only','export history cannot be deleted');select throws_ok($$select public.record_export_event('2d000000-0000-4000-8000-000000000001','1d000000-0000-4000-8000-000000000003','outside-export-01','pl','csv','2026-01-01','2026-12-31',1,repeat('c',64),'{}')$$,'P0001','Not authorized to export this workspace','nonmembers cannot record exports');
set local role authenticated;select set_config('request.jwt.claim.sub','1d000000-0000-4000-8000-000000000002',true);select is((select count(*)::integer from public.export_events),1,'workspace accountants can read export history');select set_config('request.jwt.claim.sub','1d000000-0000-4000-8000-000000000003',true);select is((select count(*)::integer from public.export_events),0,'other workspaces cannot read export history');reset role;
select throws_ok($$insert into public.export_events(workspace_id,requested_by,request_id,report_type,export_format,period_from,period_to,row_count,content_sha256)values('2d000000-0000-4000-8000-000000000001','1d000000-0000-4000-8000-000000000001','bad-hash-export','pl','csv','2026-01-01','2026-12-31',0,'unsafe')$$,'23514',null,'invalid content hashes are rejected');select * from finish();rollback;
